<div class="page-heading"><div><p class="eyebrow">Vendor workspace</p><h1>Inventory</h1><p>Every stock change is recorded in the movement history.</p></div></div>
<div class="alert alert-info"><span aria-hidden="true">i</span><div>Student and POS orders reserve stock when placed. Cancellations and rejections return reserved stock automatically.</div></div>
<?php if ($items): ?><div class="table-wrap"><table><thead><tr><th>Food</th><th>On hand</th><th>Low-stock threshold</th><th>Status</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><strong><?= h($item['food_name']) ?></strong></td><td><?= h(number_format((float) $item['quantity'], 2)) ?> <?= h($item['unit']) ?></td><td><?= h(number_format((float) $item['low_stock_threshold'], 2)) ?> <?= h($item['unit']) ?></td><td><?php $status=(float) $item['quantity'] <= (float) $item['low_stock_threshold'] ? 'PENDING' : 'ACTIVE'; $badgeLabel=$status === 'PENDING' ? 'Low stock' : 'In stock'; require APP_ROOT . '/views/components/status-badge.php'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><h2>No inventory yet</h2><p>Inventory rows are created when you add a food.</p></div><?php endif; ?>
<div class="dashboard-grid" style="margin-top:18px">
  <section class="panel"><h2 class="panel-title">Record a movement</h2><form method="post" action="<?= h(app_url('vendor.inventory.move')) ?>" class="form-grid" data-submit-feedback><?= csrf_field() ?><div class="form-field"><label for="food-id">Food</label><select id="food-id" name="food_id" required><?php foreach ($items as $item): ?><option value="<?= (int) $item['food_id'] ?>"><?= h($item['food_name']) ?> · <?= h(number_format((float) $item['quantity'], 2)) ?> <?= h($item['unit']) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="movement-type">Movement</label><select id="movement-type" name="movement_type" required><option value="RESTOCK">Restock</option><option value="PURCHASE">Purchase</option><option value="WASTE">Waste</option><option value="ADJUSTMENT">Adjustment</option></select></div><div class="form-field"><label for="quantity">Quantity</label><input id="quantity" type="number" name="quantity" min="0" step="0.01" required><span class="field-hint">For adjustment, enter the new total on-hand amount.</span></div><div class="form-field"><label for="note">Note <span class="muted">(optional)</span></label><input id="note" name="note" maxlength="240" placeholder="Supplier, reason, or note"></div><div class="form-field full"><button class="button" type="submit" data-loading-text="Recording…"<?= !$items ? ' disabled' : '' ?>>Save inventory movement</button></div></form></section>
  <section class="panel"><h2 class="panel-title">Recent movements</h2><?php if ($movements): ?><div class="activity-list"><?php foreach ($movements as $movement): ?><div class="activity-item"><span class="activity-dot" aria-hidden="true"></span><div class="spread"><div><strong><?= h($movement['food_name']) ?></strong><div class="muted small"><?= h($movement['movement_type']) ?> · <?= h(format_datetime($movement['created_at'])) ?></div><div class="muted tiny"><?= h($movement['note'] ?: ($movement['changed_by_name'] ?? '')) ?></div></div><strong><?= (float) $movement['quantity_change'] > 0 ? '+' : '' ?><?= h(number_format((float) $movement['quantity_change'], 2)) ?></strong></div></div><?php endforeach; ?></div><?php else: ?><p class="muted">Movement history will appear after stock is recorded.</p><?php endif; ?></section>
</div>
